<?php

namespace Database\Seeders;

use App\Models\HelpGuide;
use Illuminate\Database\Seeder;

/**
 * Help Desk — the starting "!" quick guide for each CRM / portal screen (topic = the key the screen
 * asks for, CRM route meta `help`). Only adds topics that don't exist yet, so re-running it never
 * overwrites what an admin changed in Admin › Help Desk. Also run by the help_guides migration.
 */
class HelpGuideSeeder extends Seeder
{
    public function run(): void
    {
        foreach ($this->guides() as $topic => $guide) {
            HelpGuide::firstOrCreate(['topic' => $topic], $guide + ['status' => true]);
        }
    }

