            'credits' => [
                'title' => 'Credits',
                'icon' => 'fa-coins',
                'intro' => 'Credits are a pay-as-you-go top-up on top of your plan. When your plan\'s listings or premium listings for the month are used up, credits let you keep going without changing your plan.',
                'features' => [
                    ['icon' => 'fa-layer-group', 'title' => 'Your plan at a glance', 'text' => 'Your plan panel shows how many new listings and premium listings you have used this month, and when the allowance resets. Credits are only needed beyond it.'],
                    ['icon' => 'fa-building', 'title' => 'Extra listings', 'text' => 'Once your plan\'s listings are used up, Add Property offers to add the listing with credits. The cost depends on its category, offering, type and price, and it is charged when you save.'],
                    ['icon' => 'fa-star', 'title' => 'Premium with credits', 'text' => 'In the Make premium window, choose Pay with Credits to make a listing premium for 7, 15 or 30 days without using your plan\'s premium allowance.'],
                    ['icon' => 'fa-calculator', 'title' => 'Credit calculator', 'text' => 'Describe a listing to see what an extra listing and each Premium length cost, in credits and in AED.'],
                    ['icon' => 'fa-plus', 'title' => 'Buy credits', 'text' => 'Choose an amount, check the total with VAT, and pay by card. The credits are added straight away.'],
                    ['icon' => 'fa-receipt', 'title' => 'History and export', 'text' => 'Every purchase, spend, refund and expiry is listed with the listing it was for. Filter by reference or dates and export it as CSV.'],
