                'steps' => [
                    ['title' => 'Use your plan first', 'text' => 'Your plan\'s monthly listings and premium listings are always used before any credits.'],
                    ['title' => 'Check the cost', 'text' => 'Open the Credit calculator to see what you will need.'],
                    ['title' => 'Buy credits', 'text' => 'Click Buy credits, pick an amount and pay by card.'],
                    ['title' => 'Spend them', 'text' => 'Add a listing or make one premium. When your plan has no room left, you are offered to pay with credits.'],
                    ['title' => 'Keep an eye on them', 'text' => 'The small Credits card in the sidebar shows your balance and when your plan\'s limit is reached.'],
                ],
                'tips' => [
                    'Credits expire after their validity period (shown when you buy). The ones that expire first are used first.',
                    'Cancelling a premium paid with credits before it starts gives the credits back. Stopping it early does not.',
                    'If you work in an agency, the agency owns the plan and the credits. Ask the agency to add credits when its listings are used up.',
                    'Credits are not needed while your plan still has room — the sidebar card only appears when they matter.',
