            ],
            'premium' => [
                'title' => 'Premium',
                'icon' => 'fa-star',
                'intro' => 'Premium listings get a Premium badge and appear in the Premium section on the website. This page shows all your live and scheduled premium listings from Properties and Commercial in one place.',
                'features' => [
