            'profile' => [
                'title' => 'My Profile',
                'icon' => 'fa-user-edit',
                'intro' => 'Keep your details, licenses and KYC documents up to date, and submit them for approval. Approval unlocks Leads, Reports and listings, and your profile also feeds your public page on the website.',
