            'property-finder' => [
                'title' => 'Property Finder',
                'icon' => 'fa-house-chimney',
                'intro' => 'Bring your Property Finder listings into MW Realty as properties: all of them once, then just the new ones. MW Realty reviews each imported listing before it can go on the website.',
                'features' => [
                    ['icon' => 'fa-key', 'title' => 'Connect with your API keys', 'text' => 'Paste your Property Finder API key and API secret and click Verify & connect. They are checked with Property Finder before saving and stored encrypted.'],
                    ['icon' => 'fa-cloud-arrow-down', 'title' => 'Import your listings', 'text' => 'Title, description, price, beds, baths, size, location and map pin, photos (watermarked), amenities and permit number are brought in.'],
                    ['icon' => 'fa-rotate', 'title' => 'Sync new listings', 'text' => 'After the first import, Sync new listings brings in only what you added on Property Finder since the last sync. Re-check all goes through every live listing again.'],
                    ['icon' => 'fa-clone', 'title' => 'No duplicates', 'text' => 'Each listing is imported once. Drafts are skipped, and so is any listing whose permit you already have here.'],
                    ['icon' => 'fa-user-tie', 'title' => 'Assigned to the right agent', 'text' => 'For an agency, each listing goes to the agent with the same email or name as the Property Finder agent. If none matches, no agent is set and the agency can assign one.'],
                    ['icon' => 'fa-chart-simple', 'title' => 'Live progress', 'text' => 'The page shows how many listings were imported, already here or failed, while the import runs in the background.'],
                ],
                'steps' => [
                    ['title' => 'Connect', 'text' => 'Paste your API key and secret (find them in PF Expert under API settings, or ask your Property Finder account manager) and click Verify & connect. Nothing is imported yet.'],
                    ['title' => 'Import', 'text' => 'Click Import all listings when you are ready. It runs in the background, so you can leave the page.'],
                    ['title' => 'Review', 'text' => 'Imported listings stay off the website until MW Realty reviews them. You are notified when they are approved or rejected.'],
                    ['title' => 'Live', 'text' => 'Approved listings go live if their permit details are complete. Otherwise, complete the permit in the property form to publish them.'],
                    ['title' => 'Keep it up to date', 'text' => 'Click Sync new listings whenever you add listings on Property Finder.'],
                ],
                'tips' => [
                    'Imports count toward your plan\'s listing limit. If the limit is reached, the sync stops; upgrade your plan and sync again to import the rest.',
                    'Agents in an agency see the agency\'s connection and can sync it, but only the agency can update the API keys or disconnect.',
                    'A rejected listing is removed and will not be imported again. Disconnecting keeps the listings you already imported.',
                    'Super Admin sees connected accounts and reviews imports under Review imported listings: tick listings, then Approve or Reject (with an optional reason).',
                ],
            ],
            'property-form' => [
                'title' => 'Add / Edit Property',
                'icon' => 'fa-pen-to-square',
                'intro' => 'This form holds everything about one listing, split into tabs on the left. The advertising permit in Core details decides when the listing can appear on the website.',
                'features' => [
                    ['icon' => 'fa-file-shield', 'title' => 'Permit and Validate', 'text' => 'In Core details, choose the Emirate (and for Dubai the Permit type: RERA, DTCM or None). Enter the permit number and click Validate to check it with DLD or ADREC.'],
                    ['icon' => 'fa-lock', 'title' => 'Locked fields', 'text' => 'A verified permit fills in details such as offering type, property type, location, bedrooms and size, and locks them with a padlock. They must match the permit. Raise a ticket if one needs changing.'],
                    ['icon' => 'fa-language', 'title' => 'Content language', 'text' => 'Switch languages in the Content language bar. With Auto-fill on, text you type in the first language is translated into the others, or click Translate now. You can still edit any language by hand.'],
                    ['icon' => 'fa-list-check', 'title' => 'Property Details', 'text' => 'Add the title, key features and description, plus rooms, size, price and other specifications. Unit number and Owner name are for internal use only and never shown on the website.'],
                    ['icon' => 'fa-user-tie', 'title' => 'Agent & Agency', 'text' => 'Agencies can assign one of their active agents, or leave it empty so enquiries are shared across the agency. Agents are always the agent on their own listings.'],
                    ['icon' => 'fa-map-pin', 'title' => 'Location and Nearby Places', 'text' => 'Enter the address, city, country and map coordinates. In Nearby Places, pick a type and a place and click Add, or create a New Place if it is missing.'],
                    ['icon' => 'fa-swimming-pool', 'title' => 'Amenities, Easy Access, Attributes', 'text' => 'Tick everything that applies from each list. Missing an option? Raise a ticket and the team will add it.'],
                    ['icon' => 'fa-images', 'title' => 'Images, Floor Plans and Brochure', 'text' => 'Drop in photos and reorder them; the first one is the featured image. Add floor plan rows, a downloadable floor plan file and a brochure that visitors get after sharing their contact details.'],
                ],
                'steps' => [
                    ['title' => 'Fill in Core details', 'text' => 'Choose the emirate and permit, then category, offering type, property type and location. Add availability dates if it is not available immediately.'],
                    ['title' => 'Validate the permit', 'text' => 'Enter the permit number, click Validate, and add the expiry date and QR code if asked. A green Verification successful message means it passed.'],
                    ['title' => 'Complete the other tabs', 'text' => 'Add the description, price, location, photos and the rest. Fields marked with a red star are required, and the form takes you to anything missing when you save.'],
                    ['title' => 'Save', 'text' => 'Click Save Property (or Update Property). Leave Active (visible on site) on if you want it live as soon as it is allowed.'],
                    ['title' => 'Go live or wait for approval', 'text' => 'A verified listing can go live straight away. DTCM and None (DIFC / JAFZA) listings, and any listing the form says needs approval, are checked by MW Realty first and you are told by email.'],
                ],
                'tips' => [
                    'One permit covers one listing only, and the same unit cannot be listed twice for the same purpose.',
                    'A DTCM permit is for holiday homes, so those listings can only be for rent.',
                    'The listing goes offline automatically when the permit expires. When it is close to expiry, the locked fields open again so you can enter and validate the renewed permit.',
                    'If your listing needs MW Realty approval, changing the permit, price, offering type, property type, bedrooms or size sends it back for approval. Edits to text and photos do not.',
                ],
            ],
            'property-options' => [
                'title' => 'Property Options',
                'icon' => 'fa-sliders',
                'intro' => 'Property Options are the choices on the property form, such as Property Type, Listing Type, Furnishing and Amenities. Only Super Admin manages them, and they apply to every agent and agency. Agents and agencies ask for new options with a support ticket.',
                'features' => [
                    ['icon' => 'fa-list', 'title' => 'All option lists in one place', 'text' => 'Pick a list on the left: listing form dropdowns (Property Type, Listing Type, Completion Status, Furnishing, Emirate, Rental Period), features with icons (Amenities, Easy Access, Attributes) and Nearby Place Type.'],
                    ['icon' => 'fa-plus', 'title' => 'Add and edit options', 'text' => 'Click Add option and enter the name in each active language. The first language is required. The Code is made from the name if you leave it empty.'],
                    ['icon' => 'fa-image', 'title' => 'Icons for features', 'text' => 'Amenities, Easy Access and Attributes options can have an icon (SVG or PNG, max 1 MB). It is shown on the property page.'],
                    ['icon' => 'fa-grip-lines', 'title' => 'Set the order', 'text' => 'Drag rows to set the order the options appear in on the form.'],
