                    ['title' => 'Add an option', 'text' => 'Click Add option, fill in the name for each language, add an icon if the list uses one, and click Save.'],
                    ['title' => 'Order and tidy up', 'text' => 'Drag rows into the right order, and use the pencil to rename an option.'],
                    ['title' => 'Retire old options', 'text' => 'Switch off an option that should no longer be picked. Delete it only if no listing uses it.'],
                ],
                'tips' => [
                    'An option used by listings cannot be deleted. Switch it off instead.',
                    'Once listings use an option, its Code is locked. You can still rename its labels.',
                    'Property Type, Listing Type and Completion Status also appear in the website search, so changes there are visible to visitors.',
                ],
            ],
            'reports' => [
                'title' => 'Reports',
                'icon' => 'fa-chart-pie',
                'intro' => 'Charts and figures about your leads, listings and closed deals. Use them to see what is working and where to focus.',
                'features' => [
                    ['icon' => 'fa-calendar', 'title' => 'Date range', 'text' => 'Switch between 7 Days, 30 Days, 90 Days and 12 Months at the top right. Every report updates to that period.'],
                    ['icon' => 'fa-address-book', 'title' => 'Leads report', 'text' => 'Total Leads, Closed Leads and Conversion Rate, plus Leads Over Time, Leads by Source, Leads by Stage and your Most Enquired Properties.'],
                    ['icon' => 'fa-building', 'title' => 'Properties report', 'text' => 'Listings Added Over Time, Sale vs Rent, Residential vs Commercial, By Property Type, and your Top Properties by Leads.'],
